<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Nova fiscalização</title><link rel="stylesheet" href="/assets/css/app.css"></head><body class="app-body"><div class="shell"><aside class="sidebar"><div class="brand">Fiscaliza Obras</div><nav><a href="/">Visão geral</a><a href="/works?condo=<?=(int)$work['condominium_id']?>">Obras</a><a class="active" href="/inspection/new?work=<?=(int)$work['id']?>">Nova fiscalização</a><a href="/settings?condo=<?=(int)$work['condominium_id']?>">Painel do Fiscal</a></nav></aside><main class="content"><header class="topbar"><div><p class="eyebrow"><?=htmlspecialchars($work['condominium_name'])?></p><h1>Fiscalização · Unidade <?=htmlspecialchars($work['unit'])?></h1><p class="muted">Checklist configurado especificamente para este condomínio.</p></div><a class="button secondary" href="/work?id=<?=(int)$work['id']?>">← Voltar</a></header><section class="panel"><form method="post" action="/inspection/create-dynamic" enctype="multipart/form-data" class="form-stack"><input type="hidden" name="_token" value="<?=htmlspecialchars(Csrf::token())?>"><input type="hidden" name="work_id" value="<?=(int)$work['id']?>"><div class="form-grid"><label>Etapa<input name="stage" placeholder="Ex.: Demolição, elétrica, acabamento"></label><label>Resultado<select name="result"><option value="COMPLIANT">Conforme</option><option value="WITH_ISSUES">Com apontamentos</option><option value="CRITICAL">Crítica</option></select></label><label class="full">Observações<textarea name="notes" rows="4"></textarea></label></div><h3>Checklist do condomínio</h3><?php if(!$items):?><p class="muted">Nenhum item personalizado foi configurado. O fiscal pode registrar a vistoria normalmente.</p><?php else:?><div class="check-grid"><?php foreach($items as $item):?><label><input type="checkbox" name="checklist[]" value="<?=(int)$item['id']?>"> <?=htmlspecialchars($item['label'])?><?php if($item['